/**
 * KPIAnalytics Component
 *
 * Displays:
 * 1. Request Status Distribution (Donut Chart with center metrics and table view)
 * 2. Average Resolution Time by Category (Horizontal Bar Chart with SLA target lines and color grading)
 */
export const renderTooltip =
  (SLA_TARGET, SLA_WARNING) =>
  ({ active, payload }) => {
    if (active && payload && payload[0]) {
      const data = payload[0].payload;
      const status =
        data.avgHours > SLA_TARGET
          ? "Exceeded SLA"
          : data.avgHours > SLA_WARNING
            ? "Approaching SLA"
            : "Within SLA";
      return (
        <div className="bg-white p-3 border border-gray-200 rounded-lg shadow-sm">
          <p className="font-semibold text-gray-800">{data.category}</p>
          <p className="text-sm text-gray-600">
            Avg: {data.avgHours} hours ({data.avgDays} days)
          </p>
          <p
            className={`text-sm font-semibold ${
              data.avgHours > SLA_TARGET
                ? "text-red-600"
                : data.avgHours > SLA_WARNING
                  ? "text-yellow-600"
                  : "text-green-600"
            }`}
          >
            {status}
          </p>
        </div>
      );
    }
    return null;
  };

const KPIAnalytics = () => {
  const [viewMode, setViewMode] = useState("snapshot"); // snapshot | table | trends
  const [timeRange, setTimeRange] = useState("All"); // 7D | 30D | 1Y | All | Custom
  const [customStartDate, setCustomStartDate] = useState("");
  const [customEndDate, setCustomEndDate] = useState("");
  const [customData, setCustomData] = useState(null);
  const [customLoading, setCustomLoading] = useState(false);
  const [customError, setCustomError] = useState(null);
  const [selectedSegment, setSelectedSegment] = useState(null);
  const [breakdownView, setBreakdownView] = useState("category"); // category or region
  const [kpiData, setKpiData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const data = await getKpiAnalytics();
        setKpiData(data);
      } catch (err) {
        setError("Failed to load KPI data. Please try again.");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // Fetches Custom-range trend data on demand (Apply button), since
  // the Custom response is a flat object (not nested under a range
  // key like 7D/30D/1Y/All), so it's kept in its own state.
  const fetchCustomTrend = async () => {
    if (!customStartDate || !customEndDate) return;
    try {
      setCustomLoading(true);
      setCustomError(null);
      const data = await getKpiAnalytics({
        time_range: "Custom",
        start_date: customStartDate,
        end_date: customEndDate,
      });
      setCustomData(data);
    } catch (err) {
      setCustomError("Failed to load custom range data. Please try again.");
    } finally {
      setCustomLoading(false);
    }
  };

  const SLA_TARGET = kpiData?.sla?.target_hours ?? 240;
  const SLA_WARNING = kpiData?.sla?.warning_hours ?? 200;

  // Snapshot and Table view read from the dedicated "Snapshot" bucket
  // (previously reused "All", but backend now separates them - per
  // request from 7/19: "All" is now per-month trend data like "1Y",
  // and "Snapshot" is the standalone aggregate).
  const snapshotData = kpiData?.body?.Snapshot;

  const resolutionData = useMemo(() => {
    if (!snapshotData?.average_resolution_time_by_category) return [];
    return snapshotData.average_resolution_time_by_category
      .map((item) => ({
        category: item.category,
        avgHours: item.avg_hours,
        avgDays: (item.avg_hours / 24).toFixed(1),
      }))
      .sort((a, b) => b.avgHours - a.avgHours);
  }, [snapshotData]);

  const statusData = useMemo(() => {
    if (!snapshotData?.request_status_distribution) return [];
    return snapshotData.request_status_distribution.map((item) => ({
      name: item.status,
      value: item.count,
    }));
  }, [snapshotData]);

  const totalRequests = snapshotData?.total_requests ?? 0;

  // Trends view reads the selected range's total_requests time series.
  // Custom uses its own separately-fetched, flat-shaped response
  // (see fetchCustomTrend above) instead of kpiData.body[timeRange].
  const trendData = useMemo(() => {
    if (timeRange === "Custom") {
      const series = customData?.body?.total_requests;
      if (!Array.isArray(series)) return [];
      return [...series].sort((a, b) => (a.period > b.period ? 1 : -1));
    }
    const series = kpiData?.body?.[timeRange]?.total_requests;
    if (!Array.isArray(series)) return [];
    return [...series].sort((a, b) => (a.period > b.period ? 1 : -1));
  }, [kpiData, timeRange, customData]);

  // Handle segment click
  const handleSegmentClick = (data) => {
    if (data && data.name) {
      setSelectedSegment(data.name);
    }
  };

  // Color mapping for resolution time based on SLA
  const getResolutionColor = (avgHours) => {
    if (avgHours > SLA_TARGET) return "#ef4444"; // Red - exceeded SLA
    if (avgHours > SLA_WARNING) return "#f59e0b"; // Yellow - approaching SLA
    return "#10b981"; // Green - within SLA
  };

  // Colors for status donut chart
  const STATUS_COLORS = {
    CREATED: "#3b82f6", // Blue
    IN_PROGRESS: "#f59e0b", // Orange
    MATCHING_VOLUNTEER: "#8b5cf6", // Purple
    RESOLVED: "#10b981", // Green
  };

  // Custom label for donut center
  /* const renderCenterLabel = ({ viewBox }) => {
    const { cx, cy } = viewBox;
    return (
      <g>
        <text
          x={cx}
          y={cy - 10}
          textAnchor="middle"
          dominantBaseline="middle"
          className="text-2xl font-bold fill-gray-800"
        >
          {totalRequests}
        </text>
        <text
          x={cx}
          y={cy + 15}
          textAnchor="middle"
          dominantBaseline="middle"
          className="text-sm fill-gray-500"
        >
          Total Requests
        </text>
      </g>
    );
  }; */

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-48 gap-3 text-gray-500">
        <div className="w-8 h-8 border-4 border-gray-200 border-t-blue-500 rounded-full animate-spin" />
        <p className="text-sm">Loading KPI data...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-32 text-red-500 text-sm">
        {error}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 gap-4">
      {/* Chart 1: Request Status Distribution (Donut Chart with Center Metrics) */}
      <ChartContainer
        title="Request Status Distribution"
        description="Breakdown of requests by current status (Click segments for details)"
      >
        {/* Controls */}
        <div className="mb-2 flex gap-2 items-center flex-wrap">
          <select
            value={viewMode}
            onChange={(e) => {
              setViewMode(e.target.value);
              setSelectedSegment(null);
            }}
            className="px-2 py-0.5 text-xs border border-gray-300 rounded bg-white"
          >
            <option value="snapshot">Snapshot</option>
            <option value="table">Table view</option>
            <option value="trends">Trends</option>
          </select>

          {viewMode === "trends" && (
            <div className="flex gap-1">
              {["7D", "30D", "1Y", "All"].map((range) => (
                <button
                  key={range}
                  type="button"
                  onClick={() => setTimeRange(range)}
                  className={`px-3 py-1 text-xs rounded ${
                    timeRange === range
                      ? "bg-blue-600 text-white"
                      : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                  }`}
                >
                  {range}
                </button>
              ))}
              <button
                type="button"
                onClick={() => setTimeRange("Custom")}
                className={`px-3 py-1 text-xs rounded ${
                  timeRange === "Custom"
                    ? "bg-blue-600 text-white"
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                }`}
              >
                Custom
              </button>
            </div>
          )}

          {viewMode === "trends" && timeRange === "Custom" && (
            <div className="flex gap-2 items-center flex-wrap mt-2 w-full">
              <label className="text-xs text-gray-600">
                From
                <input
                  type="date"
                  value={customStartDate}
                  onChange={(e) => setCustomStartDate(e.target.value)}
                  className="ml-1 px-2 py-0.5 text-xs border border-gray-300 rounded"
                />
              </label>
              <label className="text-xs text-gray-600">
                To
                <input
                  type="date"
                  value={customEndDate}
                  onChange={(e) => setCustomEndDate(e.target.value)}
                  className="ml-1 px-2 py-0.5 text-xs border border-gray-300 rounded"
                />
              </label>
              <button
                type="button"
                onClick={fetchCustomTrend}
                disabled={!customStartDate || !customEndDate || customLoading}
                className="px-3 py-1 text-xs rounded bg-blue-600 text-white disabled:bg-gray-300 disabled:cursor-not-allowed"
              >
                {customLoading ? "Loading..." : "Apply"}
              </button>
              {customError && (
                <span className="text-xs text-red-600">{customError}</span>
              )}
            </div>
          )}

          {selectedSegment && (
            <>
              <div className="px-2 py-0.5 text-xs bg-green-100 text-green-800 rounded">
                <strong>{selectedSegment}</strong>
              </div>
              <button
                onClick={() => setSelectedSegment(null)}
                className="px-2 py-0.5 text-xs bg-gray-500 text-white rounded hover:bg-gray-600"
              >
                Clear
              </button>
              <select
                value={breakdownView}
                onChange={(e) => setBreakdownView(e.target.value)}
                className="px-2 py-0.5 border border-gray-300 rounded text-xs"
              >
                <option value="category">By Category</option>
                <option value="region">By Region</option>
              </select>
            </>
          )}
        </div>

        {viewMode === "snapshot" ? (
          <>
            <ResponsiveContainer width="100%" height={280}>
              <PieChart>
                <Pie
                  data={statusData}
                  cx="50%"
                  cy="50%"
                  innerRadius={80}
                  outerRadius={120}
                  paddingAngle={0}
                  dataKey="value"
                  onClick={handleSegmentClick}
                  cursor="pointer"
                >
                  {statusData.map((entry, index) => (
                    <Cell
                      key={`cell-${index}`}
                      fill={STATUS_COLORS[entry.name] || "#6b7280"}
                      stroke={selectedSegment === entry.name ? "#000" : "none"}
                      strokeWidth={selectedSegment === entry.name ? 3 : 0}
                    />
                  ))}
                </Pie>
                <Tooltip
                  contentStyle={{
                    backgroundColor: "#fff",
                    border: "1px solid #e5e7eb",
                    borderRadius: "0.375rem",
                  }}
                />
                <Legend />
                <text
                  x="50%"
                  y="45%"
                  textAnchor="middle"
                  dominantBaseline="middle"
                  className="text-3xl font-bold fill-gray-800"
                >
                  {totalRequests}
                </text>
                <text
                  x="50%"
                  y="55%"
                  textAnchor="middle"
                  dominantBaseline="middle"
                  className="text-sm fill-gray-500"
                >
                  Total Requests
                </text>
              </PieChart>
            </ResponsiveContainer>

            {/* Breakdown View when segment is clicked */}
            {selectedSegment && getBreakdownData && (
              <div className="mt-4 p-4 bg-blue-50 rounded-lg border border-blue-200">
