                            ? "Time Period"
                            : "Region"}
                        </th>
                        <th className="px-4 py-2 text-left text-xs font-medium text-gray-500 uppercase">
                          Count
                        </th>
                      </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                      {getBreakdownData.map((item, index) => (
                        <tr key={index}>
                          <td className="px-4 py-2 text-sm text-gray-900">
                            {item.name}
                          </td>
                          <td className="px-4 py-2 text-sm font-medium text-gray-900">
                            {item.count}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <p className="text-xs text-gray-500 mt-2">
                  Note: Full category/region breakdown requires additional data
                  fields in the mock JSON
                </p>
              </div>
            )}
          </>
        ) : viewMode === "table" ? (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Count
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Percentage
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {statusData.map((item, index) => (
                  <tr key={index}>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center">
                        <div
                          className="h-4 w-4 rounded-full mr-2"
                          style={{
                            backgroundColor:
                              STATUS_COLORS[item.name] || "#6b7280",
                          }}
                        ></div>
                        <span className="text-sm font-medium text-gray-900">
                          {item.name}
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {item.value}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                      {((item.value / totalRequests) * 100).toFixed(1)}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="w-full">
            {trendData.length === 0 ? (
              <div className="flex items-center justify-center h-48 text-gray-400 text-sm">
                No trend data available for {timeRange}
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={280}>
                <LineChart data={trendData} margin={{ left: 10, right: 20 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
                  <XAxis
                    dataKey="period"
                    tick={{ fontSize: 11 }}
                    stroke="#6b7280"
                  />
                  <YAxis
                    tick={{ fontSize: 12 }}
                    stroke="#6b7280"
                    allowDecimals={false}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "#fff",
                      border: "1px solid #e5e7eb",
                      borderRadius: "0.375rem",
                    }}
                  />
                  <Legend />
                  <Line
                    type="monotone"
                    dataKey="total_requests"
                    name="Total Requests"
                    stroke="#3b82f6"
                    strokeWidth={2}
                    dot={{ r: 3 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            )}
          </div>
        )}
      </ChartContainer>

      {/* Chart 2: Average Resolution Time by Category with SLA Lines */}
      <ChartContainer
        title="Average Resolution Time by Category"
        description={`SLA Target: ${SLA_TARGET / 24} days |Warning: ${(SLA_WARNING / 24).toFixed(2)} days | Color coding: Green (within SLA), Yellow (approaching SLA), Red (exceeded SLA)`}
      >
        {resolutionData.length === 0 ? (
          <div className="flex items-center justify-center h-48 text-gray-400 text-sm">
            No resolution data available
          </div>
        ) : (
          <ResponsiveContainer width="100%" height={220}>
            <BarChart
              data={resolutionData}
              layout="vertical"
              margin={{ left: 20 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e5e7eb" />
              <XAxis
                type="number"
                tick={{ fontSize: 12 }}
                stroke="#6b7280"
                label={{ value: "Hours", position: "insideBottom", offset: -5 }}
              />
              <YAxis
                dataKey="category"
                type="category"
                tick={{ fontSize: 12 }}
                stroke="#6b7280"
                width={100}
              />
              <Tooltip
                content={renderTooltip(SLA_TARGET, SLA_WARNING)}
                /*content={({ active, payload }) => {
                  if (active && payload && payload[0]) {
                    const data = payload[0].payload;
                    const status =
                      data.avgHours > SLA_TARGET
                        ? "Exceeded SLA"
                        : data.avgHours > SLA_WARNING
                          ? "Approaching SLA"
                          : "Within SLA";
                    return (
                      <div className="bg-white p-3 border border-gray-200 rounded-lg shadow-sm">
                        <p className="font-semibold text-gray-800">
                          {data.category}
                        </p>
                        <p className="text-sm text-gray-600">
                          Avg: {data.avgHours} hours ({data.avgDays} days)
                        </p>
                        <p
                          className={`text-sm font-semibold ${
                            data.avgHours > SLA_TARGET
                              ? "text-red-600"
                              : data.avgHours > SLA_WARNING
                                ? "text-yellow-600"
                                : "text-green-600"
                          }`}
                        >
                          {status}
                        </p>
                      </div>
                    );
                  }
                  return null;
                }} */
              />

              <Legend />
              {/* SLA Target Line */}
              <ReferenceLine
                x={SLA_TARGET}
                stroke="#ef4444"
                strokeDasharray="3 3"
                label={{
                  value: "SLA Target",
                  position: "top",
                  fill: "#ef4444",
                  fontSize: 12,
                }}
              />
              {/* SLA Warning Line */}
              <ReferenceLine
                x={SLA_WARNING}
                stroke="#f59e0b"
                strokeDasharray="3 3"
                label={{
                  value: "Warning",
                  position: "top",
                  fill: "#f59e0b",
                  fontSize: 12,
                }}
              />
              <Bar dataKey="avgHours" radius={[0, 4, 4, 0]} name="Avg Hours">
                {resolutionData.map((entry, index) => (
                  <Cell
                    key={`cell-${index}`}
                    fill={getResolutionColor(entry.avgHours)}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        )}
      </ChartContainer>
    </div>
  );
};

