   reads at a glance without repeating itself in a second row. */
const RatingTick = ({ x, y, payload, index }) => (
  <g transform={`translate(${x},${y})`}>
    <text x={0} y={0} dy={12} textAnchor="middle" fontSize={11} fill="#6b7280">
