    filters.dateRange !== DEFAULT_FILTERS.dateRange ||
    filters.region !== DEFAULT_FILTERS.region ||
    filters.orgType !== DEFAULT_FILTERS.orgType ||
    customStartDate !== "" ||
    customEndDate !== "";

