export const REGIONS = ["All", "North", "South", "East", "West"];

export const ORG_TYPES = ["All", "Profit", "Non-Profit"];

// Daily data for the last 30 days (Jun 1-30, 2025)
const DAILY_DATA = [
  { date: "2025-06-01", total: 121, active: 87, collaborator: 31, profit: 45 },
